    have = {r[1] for r in
            conn.execute("PRAGMA table_info(evidence)").fetchall()}
    name, decl = _EVIDENCE_V22_COLUMN
    if name not in have:
        conn.execute("ALTER TABLE evidence ADD COLUMN %s %s" % (name, decl))


